import re
names = ["Aquachu", "Florachu", "Zap"]
for name in names:
  if re.search(r"^[AZ]", name):
    print(f"{name} starts with A or Z")
  else:
    print(f"{name} does NOT start with A or Z")
  if re.search(r"chu$", name):
    print(f"{name} ends with 'chu'")
  else:
    print(f"{name} does NOT end with 'chu'")

