import re
names = ["Aquachu", "Florachu", "Zap"]
for name in names:
  if re.search(r"^[AZ]", name):
    print(f"{name} commence par A ou Z")
  else:
    print(f"{name} ne commence PAS par A ou Z")
  if re.search(r"chu$", name):
    print(f"{name} finit par 'chu'")
  else:
    print(f"{name} ne finit PAS par 'chu'")
